/// Details on the account's acceptance of the [Stripe Services
/// Agreement](/connect/updating-accounts#tos-acceptance). This property can only be updated for
/// accounts where
/// [controller.requirement_collection](/api/accounts/object#account_object-controller-requirement_collection)
/// is `application`, which includes Custom accounts. This property defaults to a `full` service
/// agreement when empty.
public struct AccountUpdateTosAcceptance: StripeParams {
    /// The Unix timestamp marking when the account representative accepted their service agreement.
    public var date: Date?
    /// The IP address from which the account representative accepted their service agreement.
    public var ip: String?
    /// The user's service agreement type.
    public var serviceAgreement: String?
    /// The user agent of the browser from which the account representative accepted their service
    /// agreement.
    public var userAgent: String?

    public init(date: Date? = nil, ip: String? = nil, serviceAgreement: String? = nil, userAgent: String? = nil) {
        self.date = date
        self.ip = ip
        self.serviceAgreement = serviceAgreement
        self.userAgent = userAgent
    }

    public enum CodingKeys: String, CodingKey {
        case date
        case ip
        case serviceAgreement = "service_agreement"
        case userAgent = "user_agent"
    }
}
